from dataclasses import replace
from unittest.mock import patch
from bloomerp.communication.builtins.voip.registry import VOIP_PROVIDER_REGISTRY

# Generated by manage.py generate_test_cases.
from .fixtures import ComponentFixtures
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestBrowserTokenComponent(ComponentFixtures, BloomerpComponentTestCase):
    """Tests function `browser_token` from `bloomerp/components/communication/voip/browser_token.py`."""

    view_name = "components_voip_token"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        # Add only the route scenarios this callable needs.
        return [
            RequestScenario(
                name="Provider definition selects the browser driver",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_driver,
                expected=ExpectedResult(
                    response_validators=[
                        self.json_key_equals("driver", "alternate-sdk")
                    ]
                ),
            ),
            RequestScenario(
                name="Provider without a browser driver cannot issue a token",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_no_driver,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Authorized operation",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_request,
                expected=ExpectedResult(response_validators=[self.validate_no_secrets]),
            ),
            RequestScenario(
                name="Reject unauthorized operation",
                method="POST",
                user=self.normal_user,
                prepare=self.revoke_line,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Login required",
                method="POST",
                prepare=self.prepare_request,
                expected=ExpectedResult(status_code=302),
            ),
        ]

    def prepare_driver(self, scenario: RequestScenario) -> None:
        """Change only provider metadata to select a different frontend transport."""
        self.prepare_request(scenario)
        provider = replace(
            VOIP_PROVIDER_REGISTRY.get(self.connection.provider),
            browser_driver="alternate-sdk",
        )
        self.enterContext(
            patch.dict(VOIP_PROVIDER_REGISTRY._registry, {provider.key: provider})
        )

    def prepare_no_driver(self, scenario: RequestScenario) -> None:
        """Keep voice access but declare no browser transport support."""
        self.prepare_request(scenario)
        provider = replace(
            VOIP_PROVIDER_REGISTRY.get(self.connection.provider), browser_driver=""
        )
        self.enterContext(
            patch.dict(VOIP_PROVIDER_REGISTRY._registry, {provider.key: provider})
        )
